    cid = ctx.create_cell("def launch_minimal_pairs_prepare():\n    import hashlib, json, os, subprocess, sys\n    from pathlib import Path\n    root = Path('/marimo/results/rq2/minimal_pairs_v3')\n    job = root / 'jobs' / 'prepare'\n    job.mkdir(parents=True, exist_ok=True)\n    if (job / 'exit.json').exists():\n        print('Job already finished:', (job / 'exit.json').read_text())\n        return\n    if (job / 'launch_intent.json').exists():\n        print('Launch already recorded. Inspect saved PID/log; do not launch again.')\n        return\n    with (job / 'launch_intent.json').open('x') as f:\n        json.dump({'stage': 'prepare', 'user_confirmed_free': True, 'paid_authorized': False}, f)\n        f.flush()\n        os.fsync(f.fileno())\n    with (job / 'worker.log').open('ab') as log:\n        process = subprocess.Popen([sys.executable, '-B', '-u', '/marimo/domains/menu_planning/scripts/minimal_pairs/job_supervisor.py', 'prepare'], stdout=log, stderr=subprocess.STDOUT, start_new_session=True)\n    with (job / 'pid.json').open('x') as f:\n        json.dump({'pid': process.pid}, f)\n    print('Started minimal-pairs prepare, PID', process.pid, 'on the confirmed free runtime. Progress is saved on disk.')\nlaunch_minimal_pairs_prepare()\n", name='minimal_pairs_prepare', hide_code=False)
